from pathlib import Path
import json,pickle,copy,base64,hashlib
B=Path('/home/junhao/quan/parallel_test_solver/CCMKCP');H=B/'work/r02_cvar_budget_20261127';assert Path.cwd()==B
code=base64.b64decode('');scope={};exec(code,scope);verify=scope['verify_adaptive'];checks=0
for fixture,capacity in [('LAB_3_2_500_',.5),('LAB_2_2_500_',1.25)]:
 raw=json.loads((H/'integration60'/fixture/'S10_search.json').read_text());D=H/'fixtures'/fixture
 groups=pickle.loads((D/'node_to_factor.pkl').read_bytes());groups=[groups[k] for k in sorted(groups)] if isinstance(groups,dict) else groups
 costs=[float(x) for x in (D/'cost.txt').read_text().split()];samples=[(D/(str(j)+'_sample.txt')).read_text().split() for j in range(len(costs))]
 verify(raw,groups,costs,samples,capacity);checks+=1
 for path,value in [(('adaptive_RO_model','probability_coverage_claim'),True),(('adaptive_RO_model','gamma_max_exact'),'99999'),(('adaptive_RO_model','historical_solution_inputs'),True),(('adaptive_RO_model','CDF_solution_probability_monotonicity_claim'),True),(('adaptive_RO_statistics','rational_verified_unique'),9999),(('adaptive_RO_statistics','no_LSS_calls_in_generator'),False)]:
  bad=copy.deepcopy(raw);bad[path[0]][path[1]]=value
  try:verify(bad,groups,costs,samples,capacity)
  except AssertionError:checks+=1
  else:raise AssertionError('accepted tamper '+str(path))
 for field,value in [('gamma','0'),('budget_worst_sum','999999'),('own_run_raw_samples',False),('robust_slack','999999')]:
  bad=copy.deepcopy(raw);bad['adaptive_RO_proposals'][0][field]=value
  try:verify(bad,groups,costs,samples,capacity)
  except AssertionError:checks+=1
  else:raise AssertionError('accepted proposal tamper '+field)
 for field,value in [('lambda','-1'),('dual_lower','999999')]:
  if raw['adaptive_RO_cost_cuts']:
   bad=copy.deepcopy(raw);bad['adaptive_RO_cost_cuts'][0][field]=value
   try:verify(bad,groups,costs,samples,capacity)
   except AssertionError:checks+=1
   else:raise AssertionError('accepted cost cut tamper '+field)
result={'status':'PASS','checks':checks,'reader_sha256':hashlib.sha256(code).hexdigest(),'no_solver_or_sampler_import':True}
(H/'ADAPTIVE_READER_TEST.json').write_text(json.dumps(result,indent=2));print(json.dumps(result))
